(window.theoremosSources??={})["openai_cartier_chart_compactness_support"]={"Challenge.lean":"import OAI.AlgebraicGeometry.CartierSections.FieldTopology\nimport OAI.AlgebraicGeometry.CartierSections.FieldRetraction\n\nnamespace OAI\n\nnoncomputable section\nopen scoped BigOperators NNReal ENNReal\nnamespace CartierSections\nsection ClosedChartFieldTopology\nuniverse u\nlocal instance polynomialOrigin_isMaximal_topology {σ k : Type u} [Fintype σ] [Field k] :\n    (MvPolynomial.idealOfVars σ k).IsMaximal :=\n  polynomialOrigin_isMaximal\n\nvariable {σ k R A K : Type u} [Fintype σ] [Field k] [IsAlgClosed k]\n  [CommRing R] [CommRing A] [IsLocalRing R] [IsLocalRing A] [IsNoetherianRing A]\n  [IsDomain A] [Field K] [Algebra A K] [IsFractionRing A K]\n  [Algebra (MvPolynomial σ k) R] [Algebra (MvPolynomial σ k) A]\n  [Algebra k A] [IsScalarTower k (MvPolynomial σ k) A]\n  [Algebra R A] [IsScalarTower (MvPolynomial σ k) R A]\n  [IsLocalization.AtPrime R (MvPolynomial.idealOfVars σ k)]\n  [IsLocalHom (algebraMap R A)] [Algebra.FormallyUnramified R A]\n  [Algebra.EssFiniteType R A] [Algebra.FormallyEtale (MvPolynomial σ k) A]\n\nlemma isCompact_closedChartFieldRetraction_cone\n    (a : σ → NNReal) (ha : ∀ i, 0 < a i) :\n    IsCompact ((fun w : σ → NNReal => fun x : K =>\n      closedChartFieldRetraction (σ := σ) (k := k) (R := R) (A := A) w x) ''\n      normalizedWeights a) := by\n  sorry\n\nend ClosedChartFieldTopology\nend CartierSections\n\nend\n\nend OAI\n","OAI/AlgebraicGeometry/CartierSections/ChartCompletion.lean":"/-\nCopyright (c) 2026 OpenAI. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: OpenAI\n-/\nimport OAI.AlgebraicGeometry.CartierSections.InfinitesimalCharts\nimport Mathlib.RingTheory.AdicCompletion.AsTensorProduct\nimport Mathlib.RingTheory.AdicCompletion.LocalRing\nimport Mathlib.RingTheory.Flat.FaithfullyFlat.Algebra\nimport Mathlib.RingTheory.MvPowerSeries.Equiv\n\nnamespace OAI\n\n/-!\n# Completion coordinates for étale charts\n\nCompatible infinitesimal isomorphisms identify an étale chart completion with a\npower-series ring. Expansion through a Noetherian local completion is faithfully flat.\n-/\n\nnamespace CartierSections\n\nattribute [local instance 10001] scalarTower_self\nsection CompletionIsomorphism\nvariable {R A : Type*} [CommRing R] [CommRing A] [Algebra R A]\n\n/-- Evaluation of an adic completion commutes with reduction to a lower ideal power. -/\ntheorem completion_eval_factor (I : Ideal R) {m n : ℕ} (h : m ≤ n)\n    (x : AdicCompletion I R) :\n    Ideal.Quotient.factorₐ R (Ideal.pow_le_pow_right h) (AdicCompletion.evalₐ I n x) =\n      AdicCompletion.evalₐ I m x := by\n  have hx := congrArg (Ideal.Quotient.factor (show (I^m • ⊤ : Ideal R) ≤ I^m\n    from le_of_eq (Ideal.mul_top _))) (x.property h)\n  simpa [AdicCompletion.evalₐ, AdicCompletion.eval,\n    AdicCompletion.transitionMap, Submodule.factorPow] using hx\n\n/-- Evaluation on infinitesimal neighbourhoods is compatible with the maps induced\nby an algebra map. -/\ntheorem quotientPowerMap_eval_compatible (I : Ideal R) {m n : ℕ} (h : m ≤ n) :\n    (Ideal.Quotient.factorₐ R\n      (Ideal.pow_le_pow_right (I := I.map (algebraMap R A)) h)).comp\n      ((quotientPowerMap I n).comp (AdicCompletion.evalₐ I n)) =\n        (quotientPowerMap I m).comp (AdicCompletion.evalₐ I m) := by\n  rw [← AlgHom.comp_assoc, quotientPowerMap_factor I h, AlgHom.comp_assoc]\n  congr 1\n  ext x\n  exact completion_eval_factor I h x\n\n/-- The completion map induced by an algebra map. -/\nnoncomputable def chartCompletionMap (I : Ideal R) :\n    AdicCompletion I R →ₐ[R] AdicCompletion (I.map (algebraMap R A)) A :=\n  AdicCompletion.liftAlgHom _\n    (fun n => (quotientPowerMap I n).comp (AdicCompletion.evalₐ I n))\n    (quotientPowerMap_eval_compatible I)\n\n@[simp] theorem chartCompletionMap_eval (I : Ideal R) (n : ℕ) (x : AdicCompletion I R) :\n    AdicCompletion.evalₐ (I.map (algebraMap R A)) n (chartCompletionMap I x) =\n      quotientPowerMap I n (AdicCompletion.evalₐ I n x) :=\n  AdicCompletion.evalₐ_liftAlgHom _ _ (quotientPowerMap_eval_compatible I) n x\n\n/-- Étale charts with trivial residue extension have the same completion.\nThis is derived from formal lifting and uniqueness at every order. -/\ntheorem chartCompletionMap_bijective [Algebra.FormallyEtale R A]\n    (I : Ideal R) (hI : Function.Bijective (quotientBaseMap (A := A) I)) :\n    Function.Bijective (chartCompletionMap (A := A) I) := by\n  classical\n  let J := I.map (algebraMap R A)\n  let e (n : ℕ) := AlgEquiv.ofBijective (quotientPowerMap (A := A) I n)\n    (etale_quotient_power_bijective I hI n)\n  let g (n : ℕ) : AdicCompletion J A →ₐ[R] R ⧸ I^n :=\n    (e n).symm.toAlgHom.comp ((AdicCompletion.evalₐ J n).restrictScalars R)\n  have hg {m n : ℕ} (h : m ≤ n) :\n      (Ideal.Quotient.factorₐ R (Ideal.pow_le_pow_right h)).comp (g n) = g m := by\n    ext x\n    apply (e m).injective\n    change quotientPowerMap I m\n      (Ideal.Quotient.factorₐ R (Ideal.pow_le_pow_right h) ((e n).symm (AdicCompletion.evalₐ J n x))) = _\n    have hfac := AlgHom.congr_fun (quotientPowerMap_factor (A := A) I h)\n      ((e n).symm (AdicCompletion.evalₐ J n x))\n    simp only [AlgHom.comp_apply] at hfac\n    rw [← hfac]\n    change Ideal.Quotient.factorₐ R (Ideal.pow_le_pow_right h)\n      (e n ((e n).symm (AdicCompletion.evalₐ J n x))) = e m ((e m).symm (AdicCompletion.evalₐ J m x))\n    rw [(e n).apply_symm_apply, (e m).apply_symm_apply]\n    exact completion_eval_factor J h x\n  let inv : AdicCompletion J A →ₐ[R] AdicCompletion I R :=\n    AdicCompletion.liftAlgHom I g (fun h => hg h)\n  have hleft : Function.LeftInverse inv (chartCompletionMap (A := A) I) := by\n    intro x\n    apply AdicCompletion.ext_evalₐ\n    intro n\n    rw [AdicCompletion.evalₐ_liftAlgHom]\n    change (e n).symm (AdicCompletion.evalₐ J n (chartCompletionMap I x)) = _\n    rw [chartCompletionMap_eval]\n    exact (e n).symm_apply_apply _\n  have hright : Function.RightInverse inv (chartCompletionMap (A := A) I) := by\n    intro x\n    apply AdicCompletion.ext_evalₐ\n    intro n\n    rw [chartCompletionMap_eval, AdicCompletion.evalₐ_liftAlgHom]\n    exact (e n).apply_symm_apply _\n  exact ⟨hleft.injective, hright.surjective⟩\n\nnoncomputable def chartCompletionEquiv [Algebra.FormallyEtale R A]\n    (I : Ideal R) (hI : Function.Bijective (quotientBaseMap (A := A) I)) :\n    AdicCompletion I R ≃ₐ[R] AdicCompletion (I.map (algebraMap R A)) A :=\n  AlgEquiv.ofBijective (chartCompletionMap I) (chartCompletionMap_bijective I hI)\nend CompletionIsomorphism\n/-- Formal coordinates on the completion of an étale polynomial chart. -/\nnoncomputable def polynomialChartSeriesEquiv\n    {σ k A : Type*} [Finite σ] [CommRing k] [CommRing A]\n    [Algebra (MvPolynomial σ k) A] [Algebra.FormallyEtale (MvPolynomial σ k) A]\n    (hI : Function.Bijective\n      (quotientBaseMap (A := A) (MvPolynomial.idealOfVars σ k))) :\n    MvPowerSeries σ k ≃ₐ[MvPolynomial σ k]\n      AdicCompletion ((MvPolynomial.idealOfVars σ k).map (algebraMap (MvPolynomial σ k) A)) A :=\n  (MvPowerSeries.toAdicCompletionAlgEquiv σ k).trans\n    (chartCompletionEquiv (MvPolynomial.idealOfVars σ k) hI)\n\n@[simp] theorem polynomialChartSeriesEquiv_coe\n    {σ k A : Type*} [Finite σ] [CommRing k] [CommRing A]\n    [Algebra (MvPolynomial σ k) A] [Algebra.FormallyEtale (MvPolynomial σ k) A]\n    (hI : Function.Bijective\n      (quotientBaseMap (A := A) (MvPolynomial.idealOfVars σ k))) (p : MvPolynomial σ k) :\n    polynomialChartSeriesEquiv hI (p : MvPowerSeries σ k) =\n      algebraMap A _ (algebraMap (MvPolynomial σ k) A p) := by\n  exact (polynomialChartSeriesEquiv hI).commutes p\n/-- The expansion map attached to an isomorphism with the maximal-ideal completion. -/\nnoncomputable def completionExpansion\n    {A S : Type*} [CommRing A] [IsLocalRing A] [CommRing S]\n    (e : S ≃+* AdicCompletion (IsLocalRing.maximalIdeal A) A) : A →+* S :=\n  e.symm.toRingHom.comp (algebraMap A _)\n\n/-- Formal expansion through a Noetherian completion is faithfully flat. -/\ntheorem completionExpansion_faithfullyFlat\n    {A S : Type*} [CommRing A] [IsLocalRing A] [IsNoetherianRing A] [CommRing S]\n    (e : S ≃+* AdicCompletion (IsLocalRing.maximalIdeal A) A) :\n    letI : Algebra A S := (completionExpansion e).toAlgebra\n    Module.FaithfullyFlat A S := by\n  let : Algebra A S := (completionExpansion e).toAlgebra\n  have : Module.FaithfullyFlat A (AdicCompletion (IsLocalRing.maximalIdeal A) A) :=\n    Module.FaithfullyFlat.of_flat_of_isLocalHom\n  let eA : S ≃ₐ[A] AdicCompletion (IsLocalRing.maximalIdeal A) A :=\n    { e with commutes' := fun a => e.apply_symm_apply (algebraMap A _ a) }\n  exact Module.FaithfullyFlat.of_linearEquiv A _ eA.toLinearEquiv\n\n/-- A formal expansion through a Noetherian local completion reflects units. -/\ntheorem completionExpansion_isLocalHom\n    {A S : Type*} [CommRing A] [IsLocalRing A] [IsNoetherianRing A] [CommRing S]\n    (e : S ≃+* AdicCompletion (IsLocalRing.maximalIdeal A) A) :\n    IsLocalHom (completionExpansion e) := by\n  constructor\n  intro a ha\n  apply (isUnit_map_iff (algebraMap A (AdicCompletion (IsLocalRing.maximalIdeal A) A)) a).mp\n  have h := ha.map e.toMonoidHom\n  simpa [completionExpansion] using h\nsection ChartExpansion\nvariable {k A σ : Type*} [CommRing k] [CommRing A] [IsLocalRing A]\n  [Algebra k A] [Algebra (MvPolynomial σ k) A] [IsScalarTower k (MvPolynomial σ k) A]\n\n/-- Expansion in completion coordinates as an algebra map over the coefficient ring. -/\nnoncomputable def chartSeriesExpansion\n    (e : MvPowerSeries σ k ≃ₐ[MvPolynomial σ k]\n      AdicCompletion (IsLocalRing.maximalIdeal A) A) : A →ₐ[k] MvPowerSeries σ k :=\n  (e.symm.restrictScalars k).toAlgHom.comp\n    (IsScalarTower.toAlgHom k A (AdicCompletion (IsLocalRing.maximalIdeal A) A))\n\n@[simp] theorem chartSeriesExpansion_toRingHom\n    (e : MvPowerSeries σ k ≃ₐ[MvPolynomial σ k]\n      AdicCompletion (IsLocalRing.maximalIdeal A) A) :\n    (chartSeriesExpansion e).toRingHom = completionExpansion e.toRingEquiv := rfl\n\n@[simp] theorem chartSeriesExpansion_coordinate\n    (e : MvPowerSeries σ k ≃ₐ[MvPolynomial σ k]\n      AdicCompletion (IsLocalRing.maximalIdeal A) A) (i : σ) :\n    chartSeriesExpansion e (algebraMap (MvPolynomial σ k) A (MvPolynomial.X i)) =\n      MvPowerSeries.X i := by\n  apply e.injective\n  change e (e.symm (algebraMap A _ (algebraMap (MvPolynomial σ k) A (MvPolynomial.X i)))) = _\n  rw [e.apply_symm_apply]\n  have he : e ((MvPolynomial.X i : MvPolynomial σ k) : MvPowerSeries σ k) =\n      algebraMap (MvPolynomial σ k) _ (MvPolynomial.X i) := by\n    simpa only [MvPowerSeries.algebraMap_apply', Algebra.algebraMap_self,\n      MvPowerSeries.map_id, RingHom.id_apply] using e.commutes (MvPolynomial.X i)\n  simpa only [MvPolynomial.coe_X,\n    IsScalarTower.algebraMap_apply (MvPolynomial σ k) A (AdicCompletion (IsLocalRing.maximalIdeal A) A)] using he.symm\nend ChartExpansion\nend CartierSections\n\nend OAI\n","OAI/AlgebraicGeometry/CartierSections/ChartRetraction.lean":"import OAI.AlgebraicGeometry.CartierSections.ExpansionValuation\nimport OAI.AlgebraicGeometry.CartierSections.ClosedCharts\n\nnamespace OAI\n\n/-!\n# Monomial retractions on closed étale charts\n\nThe completed local coordinate isomorphism defines a faithful formal\nexpansion. Its monomial valuation allows boundary faces with zero weights.\n-/\n\nnoncomputable section\nopen scoped BigOperators NNReal ENNReal\nnamespace CartierSections\n/-- Equal ideals have canonically isomorphic completions. -/\nnoncomputable def completionIdealCongr {P A : Type*} [CommRing P] [CommRing A]\n    [Algebra P A] (I J : Ideal A) (h : I = J) :\n    AdicCompletion I A ≃ₐ[P] AdicCompletion J A := by\n  subst J\n  exact AlgEquiv.refl\n\nsection ClosedRetraction\nattribute [local instance] polynomialOrigin_isMaximal\nuniverse u\nvariable {σ k R A : Type u} [Fintype σ] [Field k] [IsAlgClosed k]\n  [CommRing R] [CommRing A] [IsLocalRing R] [IsLocalRing A] [IsNoetherianRing A]\n  [Algebra (MvPolynomial σ k) R] [Algebra (MvPolynomial σ k) A]\n  [Algebra k A] [IsScalarTower k (MvPolynomial σ k) A]\n  [Algebra R A] [IsScalarTower (MvPolynomial σ k) R A]\n  [IsLocalization.AtPrime R (MvPolynomial.idealOfVars σ k)]\n  [IsLocalHom (algebraMap R A)] [Algebra.FormallyUnramified R A]\n  [Algebra.EssFiniteType R A] [Algebra.FormallyEtale (MvPolynomial σ k) A]\n\ninclude R\n\n/-- The completed coordinate isomorphism at a closed étale point. -/\nnoncomputable def closedChartEquiv : MvPowerSeries σ k ≃ₐ[MvPolynomial σ k]\n    AdicCompletion (IsLocalRing.maximalIdeal A) A := by\n  exact (polynomialChartSeriesEquiv\n    (closed_chart_base_bijective (R := R) (A := A) (σ := σ) (k := k))).trans\n    (completionIdealCongr _ _\n      (closed_chart_maximalIdeal (R := R) (A := A) (σ := σ) (k := k)))\n\nnoncomputable def closedChartExpansion : A →ₐ[k] MvPowerSeries σ k :=\n  chartSeriesExpansion (closedChartEquiv (σ := σ) (k := k) (A := A) (R := R))\n\nomit [IsNoetherianRing A] in\n@[simp] lemma closedChartExpansion_coordinate (i : σ) :\n    closedChartExpansion (σ := σ) (k := k) (A := A) (R := R)\n      (algebraMap (MvPolynomial σ k) A (MvPolynomial.X i)) = MvPowerSeries.X i :=\n  chartSeriesExpansion_coordinate _ i\n\n/-- The monomial valuation pulled back by the formal coordinate expansion. -/\nnoncomputable def closedChartRetraction (w : σ → ℝ≥0) : AddValuation A ENNReal :=\n  expansionValuation (closedChartExpansion (σ := σ) (k := k) (A := A) (R := R)) w\n\nlemma closedChartExpansion_injective :\n    Function.Injective (closedChartExpansion (σ := σ) (k := k) (A := A) (R := R)) := by\n  let e := closedChartEquiv (σ := σ) (k := k) (A := A) (R := R)\n  let : Algebra A (MvPowerSeries σ k) := (completionExpansion e.toRingEquiv).toAlgebra\n  let : Module.FaithfullyFlat A (MvPowerSeries σ k) :=\n    completionExpansion_faithfullyFlat e.toRingEquiv\n  exact FaithfulSMul.algebraMap_injective A (MvPowerSeries σ k)\n\nlemma closedChartRetraction_finite (w : σ → ℝ≥0) {f : A} (hf : f ≠ 0) :\n    closedChartRetraction (σ := σ) (k := k) (A := A) (R := R) w f < ⊤ :=\n  expansionValuation_finite _ (closedChartExpansion_injective (σ := σ) (k := k) (A := A) (R := R)) w hf\n\nend ClosedRetraction\nend CartierSections\n\nend\n\nend OAI\n","OAI/AlgebraicGeometry/CartierSections/ClosedCharts.lean":"/-\nCopyright (c) 2026 OpenAI. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: OpenAI\n-/\nimport OAI.AlgebraicGeometry.CartierSections.ChartCompletion\nimport Mathlib.FieldTheory.IsAlgClosed.Basic\nimport Mathlib.RingTheory.Localization.AtPrime.Extension\nimport Mathlib.RingTheory.Unramified.LocalRing\n\nnamespace OAI\n\n/-!\n# Closed étale coordinate charts\n\nOver an algebraically closed coefficient field, a closed unramified chart has no\nresidue extension, and its coordinate functions generate its maximal ideal.\n-/\n\nnamespace CartierSections\n/-- A local essentially finite type unramified chart over an algebraically closed\nresidue field induces an isomorphism on residue rings. -/\ntheorem local_unramified_base_bijective\n    {R A : Type*} [CommRing R] [CommRing A] [Algebra R A]\n    [IsLocalRing R] [IsLocalRing A] [IsLocalHom (algebraMap R A)]\n    [Algebra.FormallyUnramified R A] [Algebra.EssFiniteType R A]\n    [IsAlgClosed (IsLocalRing.ResidueField R)] :\n    Function.Bijective (quotientBaseMap (A := A) (IsLocalRing.maximalIdeal R)) := by\n  let e := Ideal.quotientEquivAlgOfEq R (Algebra.FormallyUnramified.map_maximalIdeal (R := R) (S := A))\n  have hb : Function.Bijective (e.toAlgHom.comp\n      (quotientBaseMap (A := A) (IsLocalRing.maximalIdeal R))) := by\n    have he : (e.toAlgHom.comp (quotientBaseMap (A := A) (IsLocalRing.maximalIdeal R))).toRingHom =\n        algebraMap (IsLocalRing.ResidueField R) (IsLocalRing.ResidueField A) := by\n      ext a\n      rfl\n    change Function.Bijective (e.toAlgHom.comp\n      (quotientBaseMap (A := A) (IsLocalRing.maximalIdeal R))).toRingHom\n    rw [he]\n    exact IsAlgClosed.algebraMap_bijective_of_isIntegral\n      (k := IsLocalRing.ResidueField R) (K := IsLocalRing.ResidueField A)\n  refine ⟨fun _ _ h => hb.injective (congrArg e h), ?_⟩\n  intro a\n  obtain ⟨r, hr⟩ := hb.surjective (e a)\n  exact ⟨r, e.injective hr⟩\n\n/-- The coordinate-origin ideal is the literal kernel of the constant\ncoefficient map. -/\ntheorem idealOfVars_eq_ker_constantCoeff {σ k : Type*} [CommRing k] :\n    MvPolynomial.idealOfVars σ k = RingHom.ker (MvPolynomial.constantCoeff (σ := σ) (R := k)) := by\n  ext p\n  rw [← pow_one (MvPolynomial.idealOfVars σ k), MvPolynomial.mem_pow_idealOfVars_iff']\n  change (∀ d : σ →₀ ℕ, Finsupp.degree d < 1 → p.coeff d = 0) ↔ p.coeff 0 = 0\n  constructor\n  · intro h\n    exact h 0 (by simp)\n  · intro h d hd\n    have he : d = 0 := (Finsupp.degree_eq_zero_iff d).mp (Nat.lt_one_iff.mp hd)\n    simpa [he] using h\n\nnoncomputable def polynomialOriginResidueEquiv {σ k : Type*} [CommRing k] :\n    MvPolynomial σ k ⧸ MvPolynomial.idealOfVars σ k ≃+* k :=\n  (Ideal.quotEquivOfEq (idealOfVars_eq_ker_constantCoeff (σ := σ) (k := k))).trans\n    (RingHom.quotientKerEquivOfSurjective (f := MvPolynomial.constantCoeff (σ := σ) (R := k))\n      (fun c => ⟨MvPolynomial.C c, MvPolynomial.constantCoeff_C σ c⟩))\n\n@[simp] theorem polynomialOriginResidueEquiv_mk {σ k : Type*} [CommRing k]\n    (p : MvPolynomial σ k) :\n    polynomialOriginResidueEquiv (Ideal.Quotient.mk (MvPolynomial.idealOfVars σ k) p) =\n      MvPolynomial.constantCoeff p := rfl\n\ntheorem polynomialOrigin_isMaximal {σ k : Type*} [Field k] :\n    (MvPolynomial.idealOfVars σ k).IsMaximal := by\n  rw [idealOfVars_eq_ker_constantCoeff]\n  exact RingHom.ker_isMaximal_of_surjective MvPolynomial.constantCoeff\n    (fun c => ⟨MvPolynomial.C c, MvPolynomial.constantCoeff_C σ c⟩)\n\nattribute [local instance] polynomialOrigin_isMaximal\n\nsection ClosedChart\nuniverse u\nvariable {σ k R A : Type u} [Field k] [CommRing R] [CommRing A]\n  [Algebra (MvPolynomial σ k) R] [Algebra (MvPolynomial σ k) A]\n  [Algebra R A] [IsScalarTower (MvPolynomial σ k) R A]\n  [IsLocalRing R] [IsLocalRing A]\n  [IsLocalization.AtPrime R (MvPolynomial.idealOfVars σ k)]\n  [IsLocalHom (algebraMap R A)]\n  [Algebra.FormallyUnramified R A] [Algebra.EssFiniteType R A]\n\ninclude R\n\n/-- Closed étale coordinate functions generate the maximal ideal. -/\ntheorem closed_chart_maximalIdeal :\n    (MvPolynomial.idealOfVars σ k).map (algebraMap (MvPolynomial σ k) A) =\n      IsLocalRing.maximalIdeal A := by\n  have := polynomialOrigin_isMaximal (σ := σ) (k := k)\n  rw [IsScalarTower.algebraMap_eq (MvPolynomial σ k) R A, ← Ideal.map_map,\n    IsLocalization.AtPrime.map_eq_maximalIdeal (MvPolynomial.idealOfVars σ k) R,\n    Algebra.FormallyUnramified.map_maximalIdeal]\n\nvariable [IsAlgClosed k]\n\n/-- The residue premise for the completion equivalence follows from a\nclosed unramified chart over the algebraically closed coefficient field. -/\ntheorem closed_chart_base_bijective :\n    Function.Bijective (quotientBaseMap (A := A) (MvPolynomial.idealOfVars σ k)) := by\n  have := polynomialOrigin_isMaximal (σ := σ) (k := k)\n  let eR := IsLocalization.AtPrime.equivQuotMaximalIdeal (MvPolynomial.idealOfVars σ k) R\n  let eK := (polynomialOriginResidueEquiv (σ := σ) (k := k)).symm.trans eR\n  have : IsAlgClosed (IsLocalRing.ResidueField R) :=\n    IsAlgClosed.of_ringEquiv k _ eK\n  let eA := Ideal.quotEquivOfEq (closed_chart_maximalIdeal (R := R) (A := A) (σ := σ) (k := k))\n  let eA' := Ideal.quotEquivOfEq (Algebra.FormallyUnramified.map_maximalIdeal (R := R) (S := A))\n  have hlocal := local_unramified_base_bijective (R := R) (A := A)\n  have heq : eA.toRingHom.comp (quotientBaseMap (A := A) (MvPolynomial.idealOfVars σ k)).toRingHom =\n      (eA'.toRingHom.comp (quotientBaseMap (A := A) (IsLocalRing.maximalIdeal R)).toRingHom).comp\n        eR.toRingHom := by\n    apply RingHom.ext\n    intro v\n    obtain ⟨p, rfl⟩ := Ideal.Quotient.mk_surjective v\n    change Ideal.Quotient.mk (IsLocalRing.maximalIdeal A) (algebraMap (MvPolynomial σ k) A p) =\n      Ideal.Quotient.mk (IsLocalRing.maximalIdeal A) (algebraMap R A (algebraMap (MvPolynomial σ k) R p))\n    rw [IsScalarTower.algebraMap_apply (MvPolynomial σ k) R A]\n  have hb : Function.Bijective (eA.toRingHom.comp\n      (quotientBaseMap (A := A) (MvPolynomial.idealOfVars σ k)).toRingHom) := by\n    rw [heq]\n    exact (eA'.bijective.comp hlocal).comp eR.bijective\n  refine ⟨fun _ _ h => hb.injective (congrArg eA h), ?_⟩\n  intro a\n  obtain ⟨p, hp⟩ := hb.surjective (eA a)\n  exact ⟨p, eA.injective hp⟩\nend ClosedChart\nend CartierSections\n\nend OAI\n","OAI/AlgebraicGeometry/CartierSections/ConeTopology.lean":"/-\nCopyright (c) 2026 OpenAI. All rights reserved.\nReleased under Apache 2.0 license.\nAuthors: OpenAI\n-/\nimport OAI.AlgebraicGeometry.CartierSections.ExpansionValuation\n\nnamespace OAI\n\n/-!\n# Compact normalized monomial cones\n\nLocal algebra for uniform Cartier sections.\n-/\n\nnoncomputable section\nopen scoped BigOperators NNReal ENNReal\n\nnamespace CartierSections.FormalMonomial\nvariable {σ k : Type*} [Fintype σ] [CommRing k]\n\n/-- A single finite subset of the support computes all nonnegative weighted\norders, including all faces. The exponents do not depend on the weights. -/\nlemma exists_finite_formula (f : MvPowerSeries σ k) :\n    ∃ T : Finset (σ →₀ ℕ), ∀ w : σ → NNReal,\n      value w f = T.inf (fun d => (Finsupp.weight w d : ENNReal)) := by\n  obtain ⟨T, hTS, hT⟩ := finite_dominated_generators {d | MvPowerSeries.coeff d f ≠ 0}\n  refine ⟨T, fun w => le_antisymm ?_ ?_⟩\n  · exact Finset.le_inf_iff.mpr fun d hd => value_le_weight w (hTS hd)\n  · apply (le_value_iff w).mpr\n    intro d hd\n    obtain ⟨e, he, hed⟩ := hT d hd\n    exact (Finset.inf_le he).trans (ENNReal.coe_le_coe.mpr (weight_mono w hed))\n\nomit [Fintype σ] in\nlemma continuous_weight (d : σ →₀ ℕ) :\n    Continuous (fun w : σ → NNReal => Finsupp.weight w d) := by\n  simp only [Finsupp.weight_apply, Finsupp.sum, nsmul_eq_mul]\n  fun_prop\n\n/-- Formal monomial evaluation is continuous on the closed cone of nonnegative weights. -/\nlemma continuous_value (f : MvPowerSeries σ k) :\n    Continuous (fun w : σ → NNReal => value w f) := by\n  obtain ⟨T, hT⟩ := exists_finite_formula f\n  simp_rw [hT]\n  exact Continuous.finset_inf_apply fun d _ => ENNReal.continuous_coe.comp (continuous_weight d)\n\nend CartierSections.FormalMonomial\n\nnamespace CartierSections\nvariable {σ k A : Type*} [Fintype σ] [Field k] [CommRing A] [Algebra k A]\n\nlemma continuous_monomial_evaluation (θ : A →ₐ[k] MvPowerSeries σ k) (f : A) :\n    Continuous (fun w : σ → NNReal => expansionValuation θ w f) :=\n  FormalMonomial.continuous_value (θ f)\n\n/-- We use the pointwise topology on actual regular-function evaluations,\nwhich is precisely the topology invoked in the E compactness argument. -/\nlemma continuous_monomial_evaluations (θ : A →ₐ[k] MvPowerSeries σ k) :\n    Continuous (fun w : σ → NNReal => fun f : A => expansionValuation θ w f) :=\n  continuous_pi fun f => continuous_monomial_evaluation θ f\n\n/-- The normalized section of a monomial cone; `a i` is the positive\ndiscrepancy of its primitive ray in the application. -/\ndef normalizedWeights (a : σ → NNReal) : Set (σ → NNReal) :=\n  {w | ∑ i, a i * w i = 1}\n\nlemma isClosed_normalizedWeights (a : σ → NNReal) :\n    IsClosed (normalizedWeights a) := by\n  change IsClosed {w : σ → NNReal | ∑ i, a i * w i = 1}\n  exact isClosed_eq (by fun_prop) continuous_const\n\nlemma isCompact_normalizedWeights (a : σ → NNReal) (ha : ∀ i, 0 < a i) :\n    IsCompact (normalizedWeights a) := by\n  refine (isCompact_Icc (a := (0 : σ → NNReal)) (b := fun i => (a i)⁻¹)).of_isClosed_subset\n    (isClosed_normalizedWeights a) ?_\n  intro w hw\n  refine ⟨fun i => bot_le, fun i => ?_⟩\n  have h : a i * w i ≤ 1 := calc\n    a i * w i ≤ ∑ j, a j * w j := Finset.single_le_sum (f := fun j => a j * w j) (fun j _ => bot_le) (Finset.mem_univ i)\n    _ = 1 := hw\n  have hd : w i ≤ (1 : NNReal) / a i := (le_div_iff₀ (ha i)).mpr (by\n    simpa only [mul_comm] using h)\n  simpa only [one_div] using hd\n\n/-- The normalized monomial cone is compact in pointwise regular-function evaluation. -/\nlemma isCompact_monomial_cone (θ : A →ₐ[k] MvPowerSeries σ k)\n    (a : σ → NNReal) (ha : ∀ i, 0 < a i) :\n    IsCompact ((fun w : σ → NNReal => fun f : A => expansionValuation θ w f) ''\n      normalizedWeights a) :=\n  (isCompact_normalizedWeights a ha).image (continuous_monomial_evaluations θ)\n\nend CartierSections\n\nnamespace CartierSections\nsection MonomialSlice\nvariable {σ k A ι J : Type*} [Fintype σ] [Finite ι]\n  [Field k] [CommRing A] [Algebra k A]\n\n/-- Literal evaluation constraints from the common lc slice, on the ambient\nspace of readings of regular functions. In use `m j` is the positive integer\nmultiplicity from E, and the normalization of discrepancy is imposed by the\nnormalized coordinate cone. -/\ndef valuationConstraints (h : A) (F : J → A) (m : J → ENNReal) : Set (A → ENNReal) :=\n  {v | v h = 1} ∩ ⋂ j, {v | m j ≤ v (F j)}\n\nomit [CommRing A] in\nlemma isClosed_valuationConstraints (h : A) (F : J → A) (m : J → ENNReal) :\n    IsClosed (valuationConstraints h F m) := by\n  exact (isClosed_eq (continuous_apply h) continuous_const).inter\n    (isClosed_iInter fun j => isClosed_le continuous_const (continuous_apply (F j)))\n\n/-- A finite union of formal-coordinate cones cut by normalized evaluation constraints. -/\ndef finiteChartSlice (θ : ι → A →ₐ[k] MvPowerSeries σ k)\n    (a : ι → σ → NNReal) (h : A) (F : J → A) (m : J → ENNReal) : Set (A → ENNReal) :=\n  (⋃ i, (fun w : σ → NNReal => fun f : A => expansionValuation (θ i) w f) ''\n    normalizedWeights (a i)) ∩ valuationConstraints h F m\n\nlemma isCompact_finiteChartSlice (θ : ι → A →ₐ[k] MvPowerSeries σ k)\n    (a : ι → σ → NNReal) (ha : ∀ i j, 0 < a i j)\n    (h : A) (F : J → A) (m : J → ENNReal) :\n    IsCompact (finiteChartSlice θ a h F m) :=\n  (isCompact_iUnion fun i => isCompact_monomial_cone (θ i) (a i) (ha i)).inter_right\n    (isClosed_valuationConstraints h F m)\n\n/-- Compactness turns simultaneous domination on every finite set of functions\ninto domination on all functions. -/\nlemma simultaneous_targets_of_finite (θ : ι → A →ₐ[k] MvPowerSeries σ k)\n    (a : ι → σ → NNReal) (ha : ∀ i j, 0 < a i j)\n    (h : A) (F : J → A) (m : J → ENNReal) (s : A → ENNReal)\n    (hfinite : ∀ T : Finset A, ∃ (i : ι) (w : σ → NNReal),\n      w ∈ normalizedWeights (a i) ∧\n      (fun f => expansionValuation (θ i) w f) ∈ valuationConstraints h F m ∧\n      ∀ f ∈ T, s f ≤ expansionValuation (θ i) w f) :\n    ∃ (i : ι) (w : σ → NNReal), w ∈ normalizedWeights (a i) ∧\n      (fun f => expansionValuation (θ i) w f) ∈ valuationConstraints h F m ∧\n      ∀ f, s f ≤ expansionValuation (θ i) w f := by\n  classical\n  let C := finiteChartSlice θ a h F m\n  have hC : IsCompact C := isCompact_finiteChartSlice θ a ha h F m\n  obtain ⟨v, hv, hb⟩ := hC.inter_iInter_nonempty (fun f => {v : A → ENNReal | s f ≤ v f})\n    (fun f => isClosed_le continuous_const (continuous_apply f)) (by\n      intro T\n      obtain ⟨i, w, hw, hc, ht⟩ := hfinite T\n      refine ⟨fun f => expansionValuation (θ i) w f, ?_, ?_⟩\n      · exact ⟨Set.mem_iUnion.mpr ⟨i, Set.mem_image_of_mem _ hw⟩, hc⟩\n      · exact Set.mem_iInter.mpr fun f => Set.mem_iInter.mpr fun hf => ht f hf)\n  obtain ⟨i, hi⟩ := Set.mem_iUnion.mp hv.1\n  obtain ⟨w, hw, rfl⟩ := hi\n  exact ⟨i, w, hw, hv.2, fun f => Set.mem_iInter.mp hb f⟩\n\nend MonomialSlice\nend CartierSections\n\nend\n\nend OAI\n","OAI/AlgebraicGeometry/CartierSections/ExpansionValuation.lean":"import OAI.AlgebraicGeometry.CartierSections.FormalValuation\nimport OAI.AlgebraicGeometry.CartierSections.Weights\n\nnamespace OAI\n\n/-!\n# Valuations induced by formal expansions\n\nA formal coordinate expansion pulls back the monomial valuation to the\noriginal ring. Injective expansions give finite values on nonzero elements.\n-/\n\nnoncomputable section\nopen scoped BigOperators NNReal ENNReal\nnamespace CartierSections\nsection ExpansionBridge\nvariable {σ k R : Type*} [Fintype σ] [Field k] [CommRing R] [Algebra k R]\n\n/-- The infimum of the real weights of nonzero coefficients. -/\ndef seriesWeight (w : σ → ℝ) (f : MvPowerSeries σ k) : ENNReal :=\n  ⨅ (d : σ →₀ ℕ) (_ : MvPowerSeries.coeff d f ≠ 0), ENNReal.ofReal (realWeight w d)\n\ndef IsMonomialInExpansion (v : AddValuation R ENNReal)\n    (θ : R →ₐ[k] MvPowerSeries σ k) (w : σ → ℝ) : Prop :=\n  ∀ f, v f = seriesWeight w (θ f)\n\nlemma coe_finsupp_weight (w : σ → ℝ≥0) (d : σ →₀ ℕ) :\n    (Finsupp.weight w d : ℝ) = realWeight (fun i => (w i : ℝ)) d := by\n  rw [Finsupp.weight_eq_sum]\n  simp [realWeight, NNReal.coe_sum, nsmul_eq_mul, mul_comm]\n\nlemma formalValue_eq_seriesWeight (w : σ → ℝ≥0) (f : MvPowerSeries σ k) :\n    FormalMonomial.value w f = seriesWeight (fun i => (w i : ℝ)) f := by\n  unfold FormalMonomial.value seriesWeight\n  congr 1\n  funext d\n  congr 1\n  funext hd\n  rw [← coe_finsupp_weight, ENNReal.ofReal_coe_nnreal]\n\n/-- Pull back a formal monomial valuation along an expansion homomorphism. -/\ndef expansionValuation (θ : R →ₐ[k] MvPowerSeries σ k) (w : σ → ℝ≥0) :\n    AddValuation R ENNReal := (FormalMonomial.valuation w).comap θ.toRingHom\n\nlemma expansionValuation_monomial (θ : R →ₐ[k] MvPowerSeries σ k) (w : σ → ℝ≥0) :\n    IsMonomialInExpansion (expansionValuation θ w) θ (fun i => (w i : ℝ)) := by\n  intro f\n  exact formalValue_eq_seriesWeight w (θ f)\n\nlemma expansionValuation_finite (θ : R →ₐ[k] MvPowerSeries σ k)\n    (hθ : Function.Injective θ) (w : σ → ℝ≥0) {f : R} (hf : f ≠ 0) :\n    expansionValuation θ w f < ⊤ := by\n  have hf' : θ f ≠ 0 := by\n    intro h\n    apply hf\n    apply hθ\n    simpa using h\n  obtain ⟨d, hd, he⟩ := FormalMonomial.value_attained w hf'\n  change FormalMonomial.value w (θ f) < ⊤\n  rw [he]\n  exact ENNReal.coe_lt_top\n\nend ExpansionBridge\nend CartierSections\n\nend\n\nend OAI\n","OAI/AlgebraicGeometry/CartierSections/FieldRetraction.lean":"import OAI.AlgebraicGeometry.CartierSections.ChartRetraction\nimport OAI.AlgebraicGeometry.CartierSections.FractionValuation\n\nnamespace OAI\n\n/-!\n# Monomial retractions on rational function fields\n\nThe closed étale chart retraction extends to the chart's fraction field.\n-/\n\nnoncomputable section\nopen scoped BigOperators NNReal ENNReal\nnamespace CartierSections\nsection ClosedRetractionField\nuniverse u\nlocal instance polynomialOrigin_isMaximal_field {σ k : Type u} [Fintype σ] [Field k] :\n    (MvPolynomial.idealOfVars σ k).IsMaximal :=\n  polynomialOrigin_isMaximal\nvariable {σ k R A K : Type u} [Fintype σ] [Field k] [IsAlgClosed k]\n  [CommRing R] [CommRing A] [IsLocalRing R] [IsLocalRing A] [IsNoetherianRing A]\n  [IsDomain A] [Field K] [Algebra A K] [IsFractionRing A K]\n  [Algebra (MvPolynomial σ k) R] [Algebra (MvPolynomial σ k) A]\n  [Algebra k A] [IsScalarTower k (MvPolynomial σ k) A]\n  [Algebra R A] [IsScalarTower (MvPolynomial σ k) R A]\n  [IsLocalization.AtPrime R (MvPolynomial.idealOfVars σ k)]\n  [IsLocalHom (algebraMap R A)] [Algebra.FormallyUnramified R A]\n  [Algebra.EssFiniteType R A] [Algebra.FormallyEtale (MvPolynomial σ k) A]\n\n/-- The retraction is a valuation of the chart's actual rational function field. -/\nnoncomputable def closedChartFieldRetraction (w : σ → NNReal) : AddValuation K (WithTop ℝ) :=\n  fractionValuation (closedChartRetraction (σ := σ) (k := k) (A := A) (R := R) w)\n    (fun _ hf => (closedChartRetraction_finite (σ := σ) (k := k) (A := A) (R := R) w hf).ne)\n\n@[simp] lemma closedChartFieldRetraction_regular (w : σ → NNReal) (f : A) :\n    closedChartFieldRetraction (σ := σ) (k := k) (R := R) (A := A) (K := K) w (algebraMap A K f) =\n      nonnegToExtendedReal (closedChartRetraction (R := R) (k := k) w f) :=\n  fractionValuation_algebraMap _ _ _\n\nend ClosedRetractionField\nend CartierSections\n\nend\n\nend OAI\n","OAI/AlgebraicGeometry/CartierSections/FieldTopology.lean":"/-\nCopyright (c) 2026 OpenAI. All rights reserved.\nReleased under Apache 2.0 license.\nAuthors: OpenAI\n-/\nimport OAI.AlgebraicGeometry.CartierSections.ConeTopology\nimport OAI.AlgebraicGeometry.CartierSections.FractionValuation\nimport Mathlib.Topology.Instances.ENNReal.Lemmas\nimport Mathlib.Topology.Order.WithTop\n\nnamespace OAI\n\n/-!\n# Continuity of valuations on fraction fields\n\nLocal algebra for uniform Cartier sections.\n-/\n\nnoncomputable section\nopen scoped BigOperators NNReal ENNReal\n\nnamespace CartierSections\n\nlemma nonnegToExtendedReal_eq_coe_toReal {x : ENNReal} (hx : x ≠ ⊤) :\n    nonnegToExtendedReal x = (x.toReal : WithTop ℝ) := by\n  lift x to NNReal using hx with x\n  rfl\n\nsection FractionFieldTopology\nvariable {T A K : Type*} [TopologicalSpace T] [CommRing A] [IsDomain A]\n  [Field K] [Algebra A K] [IsFractionRing A K]\n\n/-- A continuous family of finite local-ring valuations extends continuously\nin the pointwise topology to the actual fraction field. The value at zero is\ninfinity; for a nonzero fraction this is the difference of two finite real\ncontinuous functions. In particular, we do not apply continuity of subtraction\nat infinity minus infinity. -/\nlemma continuous_fractionValuation_apply\n    (v : T → AddValuation A ENNReal)\n    (hv : ∀ t a, a ≠ 0 → v t a ≠ ⊤)\n    (hc : ∀ a, Continuous (fun t => v t a)) (x : K) :\n    Continuous (fun t => fractionValuation (v t) (hv t) x) := by\n  by_cases hx : x = 0\n  · subst x\n    simpa only [AddValuation.map_zero] using\n      (continuous_const : Continuous (fun _ : T => (⊤ : WithTop ℝ)))\n  obtain ⟨a, b, hb, hab⟩ := IsFractionRing.div_surjective A x\n  have ha : a ≠ 0 := by\n    intro haz\n    apply hx\n    rw [← hab, haz, map_zero, zero_div]\n  have hb' : b ≠ 0 := mem_nonZeroDivisors_iff_ne_zero.mp hb\n  have hc' (a : A) (ha : a ≠ 0) : Continuous (fun t => (v t a).toReal) := by\n    rw [continuous_iff_continuousAt]\n    intro t\n    exact (ENNReal.continuousAt_toReal (hv t a ha)).comp\n      (f := fun t => v t a) (hc a).continuousAt\n  have heq : (fun t => fractionValuation (v t) (hv t) x) =\n      (fun t => (((v t a).toReal - (v t b).toReal : ℝ) : WithTop ℝ)) := by\n    funext t\n    rw [← hab, fractionValuation_ratio,\n      nonnegToExtendedReal_eq_coe_toReal (hv t a ha),\n      nonnegToExtendedReal_eq_coe_toReal (hv t b hb')]\n    rfl\n  rw [heq]\n  exact WithTop.continuous_coe.comp ((hc' a ha).sub (hc' b hb'))\n\nlemma continuous_fractionValuation_evaluations\n    (v : T → AddValuation A ENNReal)\n    (hv : ∀ t a, a ≠ 0 → v t a ≠ ⊤)\n    (hc : ∀ a, Continuous (fun t => v t a)) :\n    Continuous (fun t => fun x : K => fractionValuation (v t) (hv t) x) :=\n  continuous_pi (continuous_fractionValuation_apply v hv hc)\n\nend FractionFieldTopology\n\nsection ExpandedFractionField\nvariable {σ k A K : Type*} [Fintype σ] [Field k] [CommRing A] [IsDomain A]\n  [Algebra k A] [Field K] [Algebra A K] [IsFractionRing A K]\n\n/-- A genuine monomial valuation on a fraction field, constructed from an\ninjective formal-coordinate expansion of its local ring. -/\nnoncomputable def expandedFractionValuation\n    (θ : A →ₐ[k] MvPowerSeries σ k) (hθ : Function.Injective θ)\n    (w : σ → NNReal) : AddValuation K (WithTop ℝ) :=\n  fractionValuation (expansionValuation θ w)\n    (fun _ hf => (expansionValuation_finite θ hθ w hf).ne)\n\n@[simp] lemma expandedFractionValuation_regular\n    (θ : A →ₐ[k] MvPowerSeries σ k) (hθ : Function.Injective θ)\n    (w : σ → NNReal) (a : A) :\n    expandedFractionValuation (K := K) θ hθ w (algebraMap A K a) =\n      nonnegToExtendedReal (expansionValuation θ w a) :=\n  fractionValuation_algebraMap _ _ _\n\nlemma continuous_expandedFractionValuation_evaluations\n    (θ : A →ₐ[k] MvPowerSeries σ k) (hθ : Function.Injective θ) :\n    Continuous (fun w : σ → NNReal => fun x : K =>\n      expandedFractionValuation θ hθ w x) :=\n  continuous_fractionValuation_evaluations (expansionValuation θ)\n    (fun w _ hf => (expansionValuation_finite θ hθ w hf).ne)\n    (continuous_monomial_evaluation θ)\n\n/-- Compactness in pointwise *rational*-function evaluation, including zero\nweights, ties between monomials, and fractions having negative value. -/\nlemma isCompact_expandedFractionValuation_cone\n    (θ : A →ₐ[k] MvPowerSeries σ k) (hθ : Function.Injective θ)\n    (a : σ → NNReal) (ha : ∀ i, 0 < a i) :\n    IsCompact ((fun w : σ → NNReal => fun x : K =>\n      expandedFractionValuation θ hθ w x) '' normalizedWeights a) :=\n  (isCompact_normalizedWeights a ha).image\n    (continuous_expandedFractionValuation_evaluations θ hθ)\n\nend ExpandedFractionField\nend CartierSections\n\nend\n\nend OAI\n","OAI/AlgebraicGeometry/CartierSections/FormalValuation.lean":"import OAI.AlgebraicGeometry.CartierSections.PolynomialValuation\nimport Mathlib.RingTheory.MvPowerSeries.NoZeroDivisors\nimport Mathlib.Data.Finsupp.Order\nimport Mathlib.Data.Finsupp.PWO\n\nnamespace OAI\n\n/-!\n# Weighted valuations on formal power series\n\nDickson finiteness gives an exponent of least weight, even when some weights\nvanish. Initial homogeneous series prove multiplicativity without requiring\na unique exponent of least weight.\n-/\n\nnoncomputable section\nopen scoped BigOperators NNReal ENNReal\nnamespace CartierSections.FormalMonomial\nsection Ring\nvariable {σ k : Type*} [CommRing k]\n\n/-- Literal coefficient-weight infimum of a formal power series. -/\ndef value (w : σ → ℝ≥0) (f : MvPowerSeries σ k) : ENNReal :=\n  ⨅ (d : σ →₀ ℕ) (_ : MvPowerSeries.coeff d f ≠ 0), (Finsupp.weight w d : ENNReal)\n\nlemma le_value_iff (w : σ → ℝ≥0) {f : MvPowerSeries σ k} {a : ENNReal} :\n    a ≤ value w f ↔ ∀ d, MvPowerSeries.coeff d f ≠ 0 →\n      a ≤ (Finsupp.weight w d : ENNReal) := by\n  simp only [value, le_iInf_iff]\n\nlemma value_le_weight (w : σ → ℝ≥0) {f : MvPowerSeries σ k} {d : σ →₀ ℕ}\n    (hd : MvPowerSeries.coeff d f ≠ 0) : value w f ≤ (Finsupp.weight w d : ENNReal) :=\n  (le_value_iff w).mp le_rfl d hd\n\n/-- Dickson finiteness gives finitely many minimal exponent vectors. -/\nlemma finite_dominated_generators [Fintype σ] (S : Set (σ →₀ ℕ)) :\n    ∃ T : Finset (σ →₀ ℕ), (↑T : Set (σ →₀ ℕ)) ⊆ S ∧\n      ∀ d ∈ S, ∃ e ∈ T, e ≤ d := by\n  classical\n  let M : Set (σ →₀ ℕ) := {e | Minimal (fun a => a ∈ S) e}\n  have hM : M.Finite := by\n    apply WellQuasiOrderedLE.finite_of_isAntichain\n    intro a ha b hb hne hab\n    exact hne (le_antisymm hab (hb.2 ha.1 hab))\n  refine ⟨hM.toFinset, ?_, ?_⟩\n  · intro e he\n    exact (hM.mem_toFinset.mp he).1\n  · intro d hd\n    obtain ⟨e, hed, he⟩ := (Set.isPWO_of_wellQuasiOrderedLE S).exists_le_minimal hd\n    exact ⟨e, hM.mem_toFinset.mpr he, hed⟩\n\nlemma weight_mono (w : σ → ℝ≥0) : Monotone (Finsupp.weight w : (σ →₀ ℕ) →+ ℝ≥0) := by\n  intro a b hab\n  obtain ⟨c, rfl⟩ := exists_add_of_le hab\n  rw [map_add]\n  exact le_add_of_nonneg_right bot_le\n\nlemma exists_initial [Fintype σ] (w : σ → ℝ≥0) {f : MvPowerSeries σ k} (hf : f ≠ 0) :\n    ∃ d, MvPowerSeries.coeff d f ≠ 0 ∧\n      ∀ e, MvPowerSeries.coeff e f ≠ 0 → Finsupp.weight w d ≤ Finsupp.weight w e := by\n  classical\n  obtain ⟨e, he⟩ : ∃ e, MvPowerSeries.coeff e f ≠ 0 := by\n    by_contra h\n    push Not at h\n    apply hf\n    ext d\n    simpa using h d\n  obtain ⟨T, hTS, hT⟩ := finite_dominated_generators {d | MvPowerSeries.coeff d f ≠ 0}\n  obtain ⟨a, ha, hae⟩ := hT e he\n  obtain ⟨d, hd, hmin⟩ := Finset.exists_min_image T (Finsupp.weight w) ⟨a, ha⟩\n  refine ⟨d, hTS hd, ?_⟩\n  intro b hb\n  obtain ⟨c, hc, hcb⟩ := hT b hb\n  exact (hmin c hc).trans (weight_mono w hcb)\n\nlemma value_eq_of_initial (w : σ → ℝ≥0) {f : MvPowerSeries σ k} {d : σ →₀ ℕ}\n    (hd : MvPowerSeries.coeff d f ≠ 0)\n    (hmin : ∀ e, MvPowerSeries.coeff e f ≠ 0 → Finsupp.weight w d ≤ Finsupp.weight w e) :\n    value w f = (Finsupp.weight w d : ENNReal) := by\n  apply le_antisymm (value_le_weight w hd)\n  exact (le_value_iff w).mpr fun e he => ENNReal.coe_le_coe.mpr (hmin e he)\n\nlemma value_attained [Fintype σ] (w : σ → ℝ≥0) {f : MvPowerSeries σ k} (hf : f ≠ 0) :\n    ∃ d, MvPowerSeries.coeff d f ≠ 0 ∧ value w f = (Finsupp.weight w d : ENNReal) := by\n  obtain ⟨d, hd, hmin⟩ := exists_initial w hf\n  exact ⟨d, hd, value_eq_of_initial w hd hmin⟩\n\n@[simp] lemma value_zero (w : σ → ℝ≥0) : value (k := k) w 0 = ⊤ := by\n  simp [value]\n\n@[simp] lemma value_one [IsDomain k] (w : σ → ℝ≥0) : value (k := k) w 1 = 0 := by\n  have h : value (k := k) w 1 ≤ (Finsupp.weight w 0 : ENNReal) :=\n    value_le_weight w (by simp)\n  simpa using le_antisymm h bot_le\n\nlemma value_add (w : σ → ℝ≥0) (f g : MvPowerSeries σ k) :\n    min (value w f) (value w g) ≤ value w (f+g) := by\n  apply (le_value_iff w).mpr\n  intro d hd\n  by_cases hf : MvPowerSeries.coeff d f = 0\n  · have hg : MvPowerSeries.coeff d g ≠ 0 := by\n      intro hg\n      exact hd (by simp [hf, hg])\n    exact (min_le_right _ _).trans (value_le_weight w hg)\n  · exact (min_le_left _ _).trans (value_le_weight w hf)\n\nlemma le_value_mul (w : σ → ℝ≥0) (f g : MvPowerSeries σ k) :\n    value w f + value w g ≤ value w (f*g) := by\n  classical\n  apply (le_value_iff w).mpr\n  intro d hd\n  rw [MvPowerSeries.coeff_mul] at hd\n  obtain ⟨⟨a,b⟩, hab, hcoef⟩ := Finset.exists_ne_zero_of_sum_ne_zero hd\n  have ha : MvPowerSeries.coeff a f ≠ 0 := left_ne_zero_of_mul hcoef\n  have hb : MvPowerSeries.coeff b g ≠ 0 := right_ne_zero_of_mul hcoef\n  have hab' : a+b = d := by simpa using hab\n  rw [← hab', map_add, ENNReal.coe_add]\n  exact add_le_add (value_le_weight w ha) (value_le_weight w hb)\n\n/-- The initial homogeneous series of a given weight. -/\ndef component (w : σ → ℝ≥0) (a : ℝ≥0) (f : MvPowerSeries σ k) : MvPowerSeries σ k :=\n  fun d => if Finsupp.weight w d = a then MvPowerSeries.coeff d f else 0\n\n@[simp] lemma coeff_component (w : σ → ℝ≥0) (a : ℝ≥0)\n    (f : MvPowerSeries σ k) (d : σ →₀ ℕ) :\n    MvPowerSeries.coeff d (component w a f) =\n      if Finsupp.weight w d = a then MvPowerSeries.coeff d f else 0 := rfl\n\nlemma component_mul_at_lower_bounds (w : σ → ℝ≥0) (f g : MvPowerSeries σ k)\n    (a b : ℝ≥0)\n    (hf : ∀ d, MvPowerSeries.coeff d f ≠ 0 → a ≤ Finsupp.weight w d)\n    (hg : ∀ d, MvPowerSeries.coeff d g ≠ 0 → b ≤ Finsupp.weight w d) :\n    component w (a+b) (f*g) = component w a f * component w b g := by\n  classical\n  ext d\n  rw [coeff_component, MvPowerSeries.coeff_mul, MvPowerSeries.coeff_mul]\n  by_cases hd : Finsupp.weight w d = a+b\n  · rw [ite_eq_left hd]\n    apply Finset.sum_congr rfl\n    intro ij hij\n    rw [coeff_component, coeff_component]\n    by_cases hi : MvPowerSeries.coeff ij.1 f = 0\n    · simp [hi]\n    by_cases hj : MvPowerSeries.coeff ij.2 g = 0\n    · simp [hj]\n    have hi' := hf ij.1 hi\n    have hj' := hg ij.2 hj\n    have hs : Finsupp.weight w ij.1 + Finsupp.weight w ij.2 = a+b := by\n      rw [← map_add, Finset.HasAntidiagonal.mem_antidiagonal.mp hij, hd]\n    have hia : Finsupp.weight w ij.1 = a := le_antisymm\n      (le_of_add_le_add_right ((add_le_add (le_refl (Finsupp.weight w ij.1)) hj').trans_eq hs)) hi'\n    have hjb : Finsupp.weight w ij.2 = b := by\n      rw [hia] at hs\n      exact add_left_cancel hs\n    simp [hia, hjb]\n  · rw [ite_eq_right hd]\n    symm\n    apply Finset.sum_eq_zero\n    intro ij hij\n    rw [coeff_component, coeff_component]\n    by_cases hi : Finsupp.weight w ij.1 = a\n    · have hj : Finsupp.weight w ij.2 ≠ b := by\n        intro hj\n        apply hd\n        rw [← Finset.HasAntidiagonal.mem_antidiagonal.mp hij, map_add, hi, hj]\n      simp [hj]\n    · simp [hi]\n\nlemma component_ne_zero (w : σ → ℝ≥0) (f : MvPowerSeries σ k)\n    {d : σ →₀ ℕ} (hd : MvPowerSeries.coeff d f ≠ 0) :\n    component w (Finsupp.weight w d) f ≠ 0 := by\n  intro h\n  have hc := congrArg (MvPowerSeries.coeff d) h\n  simp only [coeff_component, map_zero] at hc\n  exact hd hc\n\nend Ring\n\nsection Domain\nvariable {σ k : Type*} [Fintype σ] [CommRing k] [IsDomain k]\n\nlemma value_mul (w : σ → ℝ≥0) (f g : MvPowerSeries σ k) :\n    value w (f*g) = value w f + value w g := by\n  classical\n  by_cases hf : f = 0\n  · simp [hf]\n  by_cases hg : g = 0\n  · simp [hg]\n  obtain ⟨a, ha, hmin_a⟩ := exists_initial w hf\n  obtain ⟨b, hb, hmin_b⟩ := exists_initial w hg\n  have hn : component w (Finsupp.weight w a + Finsupp.weight w b) (f*g) ≠ 0 := by\n    rw [component_mul_at_lower_bounds w f g _ _ hmin_a hmin_b]\n    exact mul_ne_zero (component_ne_zero w f ha) (component_ne_zero w g hb)\n  obtain ⟨d, hd⟩ : ∃ d, MvPowerSeries.coeff d\n      (component w (Finsupp.weight w a + Finsupp.weight w b) (f*g)) ≠ 0 := by\n    by_contra h\n    push Not at h\n    apply hn\n    ext d\n    simpa using h d\n  rw [coeff_component] at hd\n  have heq : Finsupp.weight w d = Finsupp.weight w a + Finsupp.weight w b := by\n    by_contra h\n    exact hd (ite_eq_right h)\n  have hcoef : MvPowerSeries.coeff d (f*g) ≠ 0 := by simpa [heq] using hd\n  apply le_antisymm _ (le_value_mul w f g)\n  rw [value_eq_of_initial w ha hmin_a, value_eq_of_initial w hb hmin_b,\n    ← ENNReal.coe_add, ← heq]\n  exact value_le_weight w hcoef\n\n/-- Genuine monomial valuation on the formal regular local ring, including\nfaces with zero weights. -/\ndef valuation (w : σ → ℝ≥0) : AddValuation (MvPowerSeries σ k) ENNReal :=\n  AddValuation.of (value w) (value_zero w) (value_one w) (value_add w) (value_mul w)\n\n@[simp] lemma valuation_apply (w : σ → ℝ≥0) (f : MvPowerSeries σ k) :\n    valuation w f = value w f := rfl\n\n/-- Nonnegative combinations of weights dominate the corresponding values. -/\nlemma combine_dominates {ι : Type*} (s : Finset ι) (c : ι → ℝ≥0)\n    (w : ι → σ → ℝ≥0) (f : MvPowerSeries σ k) :\n    ∑ i ∈ s, (c i : ENNReal) * valuation (w i) f ≤\n      valuation (Monomial.combine s c w) f := by\n  change _ ≤ value _ f\n  apply (le_value_iff _).mpr\n  intro d hd\n  rw [Monomial.weight_combine, ENNReal.ofNNReal_finsetSum]\n  simp_rw [ENNReal.coe_mul]\n  apply Finset.sum_le_sum\n  intro i hi\n  exact mul_le_mul_right (value_le_weight (w i) hd) _\n\nend Domain\nend CartierSections.FormalMonomial\n\nend\n\nend OAI\n","OAI/AlgebraicGeometry/CartierSections/FractionValuation.lean":"import Mathlib.RingTheory.Valuation.ExtendToLocalization\nimport Mathlib.RingTheory.Localization.FractionRing\nimport Mathlib.Basic.ENNReal.Basic\n\nnamespace OAI\n\n/-!\n# Extending finite valuations to a fraction field\n\nA finite nonnegative valuation on a domain extends uniquely to its fraction\nfield with values in the extended real line.\n-/\n\nnoncomputable section\nopen scoped BigOperators NNReal ENNReal\nnamespace CartierSections\n\n/-- ENNReal, used for nonnegative local-ring values, embedded in the extended\nreal additive group used on the fraction field. -/\ndef nonnegToExtendedReal : ENNReal →+ WithTop ℝ :=\n  NNReal.toRealHom.toAddMonoidHom.withTopMap\n\n@[simp] theorem nonnegToExtendedReal_top : nonnegToExtendedReal ⊤ = ⊤ := rfl\n@[simp] theorem nonnegToExtendedReal_coe (a : NNReal) :\n    nonnegToExtendedReal a = ((a : ℝ) : WithTop ℝ) := rfl\n\nlemma nonnegToExtendedReal_monotone : Monotone nonnegToExtendedReal := by\n  intro a b hab\n  by_cases hb : b = ⊤\n  · subst b; simp\n  lift b to NNReal using hb with b\n  have ha : a ≠ ⊤ := ne_top_of_le_ne_top ENNReal.coe_ne_top hab\n  lift a to NNReal using ha with a\n  simpa using hab\n\n@[simp] lemma nonnegToExtendedReal_eq_top {a : ENNReal} :\n    nonnegToExtendedReal a = ⊤ ↔ a = ⊤ := by\n  by_cases ha : a = ⊤\n  · simp [ha]\n  · lift a to NNReal using ha with a\n    simp\n\nsection LocalValuation\nvariable {A : Type*} [CommRing A]\n\n/-- Regard a nonnegative valuation as an extended-real valuation. -/\nnoncomputable def realLocalValuation (v : AddValuation A ENNReal) : AddValuation A (WithTop ℝ) :=\n  v.map nonnegToExtendedReal nonnegToExtendedReal_top nonnegToExtendedReal_monotone\n\n@[simp] lemma realLocalValuation_apply (v : AddValuation A ENNReal) (a : A) :\n    realLocalValuation v a = nonnegToExtendedReal (v a) := rfl\n\nend LocalValuation\n\nsection FractionField\nvariable {A K : Type*} [CommRing A] [IsDomain A] [Field K]\n  [Algebra A K] [IsFractionRing A K]\n\nlemma realLocalValuation_denominators (v : AddValuation A ENNReal)\n    (hv : ∀ a ≠ 0, v a ≠ ⊤) :\n    nonZeroDivisors A ≤ (AddValuation.toValuation (realLocalValuation v)).supp.primeCompl := by\n  intro a ha\n  change realLocalValuation v a ≠ ⊤\n  simpa using hv a (mem_nonZeroDivisors_iff_ne_zero.mp ha)\n\n/-- Extend a valuation that is finite on nonzero elements to the fraction field. -/\nnoncomputable def fractionValuation (v : AddValuation A ENNReal)\n    (hv : ∀ a ≠ 0, v a ≠ ⊤) : AddValuation K (WithTop ℝ) :=\n  AddValuation.ofValuation ((AddValuation.toValuation (realLocalValuation v)).extendToLocalization\n    (realLocalValuation_denominators v hv) K)\n\n@[simp] lemma fractionValuation_algebraMap (v : AddValuation A ENNReal)\n    (hv : ∀ a ≠ 0, v a ≠ ⊤) (a : A) :\n    fractionValuation (K := K) v hv (algebraMap A K a) = nonnegToExtendedReal (v a) := by\n  exact Valuation.extendToLocalization_apply_map_apply\n    (AddValuation.toValuation (realLocalValuation v))\n    (realLocalValuation_denominators v hv) K a\n\nlemma fractionValuation_ratio (v : AddValuation A ENNReal)\n    (hv : ∀ a ≠ 0, v a ≠ ⊤) (a b : A) :\n    fractionValuation (K := K) v hv (algebraMap A K a / algebraMap A K b) =\n      nonnegToExtendedReal (v a) - nonnegToExtendedReal (v b) := by\n  rw [AddValuation.map_div, fractionValuation_algebraMap, fractionValuation_algebraMap]\n\n/-- The extension is unique as a valuation of the function field. -/\nlemma fractionValuation_unique (v : AddValuation A ENNReal)\n    (hv : ∀ a ≠ 0, v a ≠ ⊤) (u : AddValuation K (WithTop ℝ))\n    (hu : ∀ a, u (algebraMap A K a) = nonnegToExtendedReal (v a)) :\n    u = fractionValuation v hv := by\n  apply DFunLike.ext\n  intro x\n  obtain ⟨a, b, hb, rfl⟩ := IsFractionRing.div_surjective (A := A) x\n  rw [u.map_div, hu, hu, fractionValuation_ratio]\n\nend FractionField\nend CartierSections\n\nend\n\nend OAI\n","OAI/AlgebraicGeometry/CartierSections/InfinitesimalCharts.lean":"/-\nCopyright (c) 2026 OpenAI. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: OpenAI\n-/\nimport Mathlib.RingTheory.Etale.Basic\nimport Mathlib.RingTheory.Ideal.Quotient.Operations\n\nnamespace OAI\n\n/-!\n# Infinitesimal neighbourhoods in formally étale charts\n\nFormal smoothness and formal unramifiedness give compatible isomorphisms on the\nquotients by powers of an ideal whenever the residue map is an isomorphism.\n-/\n\nnamespace CartierSections\n\n/-- The multiplication action of a commutative ring on itself forms a scalar tower. -/\ntheorem scalarTower_self {R : Type*} [CommRing R] : IsScalarTower R R R :=\n  IsScalarTower.right\n\nattribute [local instance 10001] scalarTower_self\n\nsection NilpotentLifting\nvariable {R A S : Type*} [CommRing R] [CommRing A] [CommRing S]\n  [Algebra R A] [Algebra R S]\n\n/-- The image of an ideal modulo a power of itself is nilpotent. -/\ntheorem quotient_reduction_nilpotent (I : Ideal S) (n : ℕ) :\n    IsNilpotent (I.map (Ideal.Quotient.mkₐ R (I^n))) := by\n  refine ⟨n, ?_⟩\n  rw [← Ideal.map_pow]\n  exact Ideal.map_quotient_self _\n\n/-- Formal smoothness lifts a residue map to every finite infinitesimal\nneighbourhood. -/\ntheorem formally_smooth_lift_to_power [Algebra.FormallySmooth R A]\n    (I : Ideal S) {n : ℕ} (hn : 0 < n) (f : A →ₐ[R] S ⧸ I) :\n    ∃ g : A →ₐ[R] S ⧸ I^n,\n      (Ideal.Quotient.factorₐ R (Ideal.pow_le_self hn.ne')).comp g = f := by\n  let e := DoubleQuot.quotQuotEquivQuotOfLEₐ R (Ideal.pow_le_self (I := I) hn.ne')\n  let g := Algebra.FormallySmooth.lift _ (quotient_reduction_nilpotent (R := R) I n)\n    (e.symm.toAlgHom.comp f)\n  refine ⟨g, ?_⟩\n  rw [← DoubleQuot.quotQuotEquivQuotOfLEₐ_comp_mkₐ R]\n  rw [AlgHom.comp_assoc, Algebra.FormallySmooth.comp_lift]\n  ext a\n  exact e.apply_symm_apply (f a)\n\n/-- Formal unramifiedness gives uniqueness of lifts of a residue map. -/\ntheorem formally_unramified_unique_to_power [Algebra.FormallyUnramified R A]\n    (I : Ideal S) {n : ℕ} (hn : 0 < n) (f g : A →ₐ[R] S ⧸ I^n)\n    (h : (Ideal.Quotient.factorₐ R (Ideal.pow_le_self hn.ne')).comp f =\n      (Ideal.Quotient.factorₐ R (Ideal.pow_le_self hn.ne')).comp g) : f = g := by\n  apply Algebra.FormallyUnramified.lift_unique\n    (I.map (Ideal.Quotient.mkₐ R (I^n))) (quotient_reduction_nilpotent (R := R) I n)\n  ext a\n  apply (DoubleQuot.quotQuotEquivQuotOfLEₐ R (Ideal.pow_le_self (I := I) hn.ne')).injective\n  have he := DoubleQuot.quotQuotEquivQuotOfLEₐ_comp_mkₐ R\n    (Ideal.pow_le_self (I := I) hn.ne')\n  exact (AlgHom.congr_fun he (f a)).trans\n    ((AlgHom.congr_fun h a).trans (AlgHom.congr_fun he (g a)).symm)\nend NilpotentLifting\n\nsection QuotientIsomorphism\nvariable {R A : Type*} [CommRing R] [CommRing A] [Algebra R A]\n\n/-- The map on each infinitesimal neighbourhood induced by the algebra map. -/\ndef quotientPowerMap (I : Ideal R) (n : ℕ) :\n    R ⧸ I^n →ₐ[R] A ⧸ (I.map (algebraMap R A))^n :=\n  Ideal.quotientMapₐ _ (Algebra.ofId R A) (by\n    rw [← Ideal.map_pow]\n    exact Ideal.le_comap_map)\n\n@[simp] theorem quotientPowerMap_mk (I : Ideal R) (n : ℕ) (r : R) :\n    quotientPowerMap (A := A) I n (Ideal.Quotient.mk (I^n) r) =\n      Ideal.Quotient.mk ((I.map (algebraMap R A))^n) (algebraMap R A r) := rfl\n\n@[simp] theorem quotientPowerMap_algebraMap (I : Ideal R) (n : ℕ) (r : R) :\n    quotientPowerMap (A := A) I n (algebraMap R (R ⧸ I^n) r) =\n      algebraMap R (A ⧸ (I.map (algebraMap R A))^n) r := by\n  exact (quotientPowerMap (A := A) I n).commutes r\n\ntheorem quotientPowerMap_factor (I : Ideal R) {m n : ℕ} (h : m ≤ n) :\n    (Ideal.Quotient.factorₐ R (Ideal.pow_le_pow_right (I := I.map (algebraMap R A)) h)).comp\n        (quotientPowerMap I n) =\n      (quotientPowerMap I m).comp (Ideal.Quotient.factorₐ R (Ideal.pow_le_pow_right (I := I) h)) := by\n  ext r\n  obtain ⟨r, rfl⟩ := Ideal.Quotient.mk_surjective r\n  rfl\n\ndef quotientBaseMap (I : Ideal R) : R ⧸ I →ₐ[R] A ⧸ I.map (algebraMap R A) :=\n  Ideal.quotientMapₐ _ (Algebra.ofId R A) Ideal.le_comap_map\n\n/-- A formally étale map which is an isomorphism modulo I is an\nisomorphism modulo every power of I. -/\ntheorem etale_quotient_power_bijective [Algebra.FormallyEtale R A]\n    (I : Ideal R) (hI : Function.Bijective (quotientBaseMap (A := A) I)) (n : ℕ) :\n    Function.Bijective (quotientPowerMap (A := A) I n) := by\n  classical\n  by_cases hn : n = 0\n  · subst n\n    have : Subsingleton (R ⧸ I^0) := by simp only [pow_zero, Ideal.one_eq_top]; infer_instance\n    have : Subsingleton (A ⧸ (I.map (algebraMap R A))^0) := by\n      simp only [pow_zero, Ideal.one_eq_top]; infer_instance\n    exact ⟨fun _ _ _ => Subsingleton.elim _ _, fun a => ⟨0, Subsingleton.elim _ _⟩⟩\n  have hn' : 0 < n := Nat.pos_of_ne_zero hn\n  let J := I.map (algebraMap R A)\n  let φ₀ : R ⧸ I →ₐ[R] A ⧸ J :=\n    Ideal.quotientMapₐ J (Algebra.ofId R A) Ideal.le_comap_map\n  have hφ₀ : Function.Bijective φ₀ := hI\n  let e := AlgEquiv.ofBijective φ₀ hφ₀\n  let f : A →ₐ[R] R ⧸ I := e.symm.toAlgHom.comp (Ideal.Quotient.mkₐ R J)\n  obtain ⟨g, hg⟩ := formally_smooth_lift_to_power I hn' f\n  have hkill : J^n ≤ RingHom.ker g := by\n    dsimp [J]\n    rw [← Ideal.map_pow, Ideal.map_le_iff_le_comap]\n    intro r hr\n    change g (algebraMap R A r) = 0\n    rw [g.commutes]\n    exact Ideal.Quotient.eq_zero_iff_mem.mpr hr\n  let q : A ⧸ J^n →ₐ[R] R ⧸ I^n := Ideal.Quotient.liftₐ (J^n) g\n    (fun a ha => hkill ha)\n  have hleft : Function.LeftInverse q (quotientPowerMap (A := A) I n) := by\n    intro r\n    obtain ⟨r, rfl⟩ := Ideal.Quotient.mk_surjective r\n    exact g.commutes r\n  have heq : (quotientPowerMap (A := A) I n).comp g = Ideal.Quotient.mkₐ R (J^n) := by\n    apply formally_unramified_unique_to_power J hn'\n    have hfactor :\n        (Ideal.Quotient.factorₐ R (Ideal.pow_le_self (I := J) hn)).comp\n            (quotientPowerMap (A := A) I n) =\n          φ₀.comp (Ideal.Quotient.factorₐ R (Ideal.pow_le_self (I := I) hn)) := by\n      ext r\n      obtain ⟨r, rfl⟩ := Ideal.Quotient.mk_surjective r\n      rfl\n    rw [← AlgHom.comp_assoc, hfactor, AlgHom.comp_assoc, hg]\n    ext a\n    exact e.apply_symm_apply (Ideal.Quotient.mk J a)\n  have hright : Function.RightInverse q (quotientPowerMap (A := A) I n) := by\n    intro a\n    obtain ⟨a, rfl⟩ := Ideal.Quotient.mk_surjective a\n    exact AlgHom.congr_fun heq a\n  exact ⟨hleft.injective, hright.surjective⟩\nend QuotientIsomorphism\nend CartierSections\n\nend OAI\n","OAI/AlgebraicGeometry/CartierSections/PolynomialValuation.lean":"import Mathlib.RingTheory.MvPolynomial.WeightedHomogeneous\nimport Mathlib.RingTheory.Valuation.Basic\nimport Mathlib.Basic.ENNReal.BigOperators\nimport Mathlib.Tactic.Ring\n\nnamespace OAI\n\n/-!\n# Weighted valuations on polynomial rings\n\nThe least weight of a nonzero coefficient defines a valuation, including\nweights with ties or zero coordinates. Nonnegative combinations of weight\nvectors give a domination inequality within a fixed coordinate chart.\n-/\n\nnoncomputable section\nopen scoped BigOperators NNReal ENNReal\nnamespace CartierSections.Monomial\n\nvariable {σ k : Type*} [CommRing k]\n\n/-- The value is the minimum monomial weight, with value infinity at zero. -/\ndef value (w : σ → ℝ≥0) (p : MvPolynomial σ k) : ENNReal :=\n  p.support.inf fun d => (Finsupp.weight w d : ENNReal)\n\n@[simp] lemma value_zero (w : σ → ℝ≥0) : value (k := k) w 0 = ⊤ := by\n  simp [value]\n\nlemma value_le_weight (w : σ → ℝ≥0) {p : MvPolynomial σ k} {d : σ →₀ ℕ}\n    (hd : d ∈ p.support) : value w p ≤ (Finsupp.weight w d : ENNReal) :=\n  Finset.inf_le hd\n\nlemma le_value_iff (w : σ → ℝ≥0) {p : MvPolynomial σ k} {a : ENNReal} :\n    a ≤ value w p ↔ ∀ d ∈ p.support, a ≤ (Finsupp.weight w d : ENNReal) :=\n  Finset.le_inf_iff\n\nlemma value_attained (w : σ → ℝ≥0) {p : MvPolynomial σ k} (hp : p ≠ 0) :\n    ∃ d ∈ p.support, value w p = (Finsupp.weight w d : ENNReal) :=\n  Finset.exists_mem_eq_inf p.support (MvPolynomial.support_nonempty.mpr hp) _\n\nlemma value_lt_top (w : σ → ℝ≥0) {p : MvPolynomial σ k} (hp : p ≠ 0) :\n    value w p < ⊤ := by\n  obtain ⟨d, hd, he⟩ := value_attained w hp\n  rw [he]\n  exact ENNReal.coe_lt_top\n\n@[simp] lemma value_one [Nontrivial k] (w : σ → ℝ≥0) : value (k := k) w 1 = 0 := by\n  simp [value]\n\nlemma value_add (w : σ → ℝ≥0) (p q : MvPolynomial σ k) :\n    min (value w p) (value w q) ≤ value w (p+q) := by\n  classical\n  apply (le_value_iff w).mpr\n  intro d hd\n  have hd' := MvPolynomial.support_add hd\n  rcases Finset.mem_union.mp hd' with hp | hq\n  · exact (min_le_left _ _).trans (value_le_weight w hp)\n  · exact (min_le_right _ _).trans (value_le_weight w hq)\n\n/-- No cancellation can create a term below the sum of the two minima. -/\nlemma le_value_mul (w : σ → ℝ≥0) (p q : MvPolynomial σ k) :\n    value w p + value w q ≤ value w (p*q) := by\n  classical\n  apply (le_value_iff w).mpr\n  intro d hd\n  obtain ⟨a, ha, b, hb, hab⟩ := Finset.mem_add.mp (MvPolynomial.support_mul p q hd)\n  subst d\n  simpa only [map_add, ENNReal.coe_add] using\n    add_le_add (value_le_weight w ha) (value_le_weight w hb)\n\n/-- At the sum of the lower bounds, the initial part of a product is the\nproduct of the initial parts. This includes non-generic tied weights. -/\nlemma component_mul_at_lower_bounds (w : σ → ℝ≥0) (p q : MvPolynomial σ k)\n    (a b : ℝ≥0)\n    (hp : ∀ d ∈ p.support, a ≤ Finsupp.weight w d)\n    (hq : ∀ d ∈ q.support, b ≤ Finsupp.weight w d) :\n    MvPolynomial.weightedHomogeneousComponent w (a+b) (p*q) =\n      MvPolynomial.weightedHomogeneousComponent w a p *\n        MvPolynomial.weightedHomogeneousComponent w b q := by\n  classical\n  ext d\n  rw [MvPolynomial.coeff_weightedHomogeneousComponent, MvPolynomial.coeff_mul,\n    MvPolynomial.coeff_mul]\n  by_cases hd : Finsupp.weight w d = a+b\n  · rw [ite_eq_left hd]\n    apply Finset.sum_congr rfl\n    intro ij hij\n    rw [MvPolynomial.coeff_weightedHomogeneousComponent,\n      MvPolynomial.coeff_weightedHomogeneousComponent]\n    by_cases hi : p.coeff ij.1 = 0\n    · simp [hi]\n    by_cases hj : q.coeff ij.2 = 0\n    · simp [hj]\n    have hi' := hp ij.1 (MvPolynomial.mem_support_iff.mpr hi)\n    have hj' := hq ij.2 (MvPolynomial.mem_support_iff.mpr hj)\n    have hs : Finsupp.weight w ij.1 + Finsupp.weight w ij.2 = a+b := by\n      rw [← map_add, Finset.HasAntidiagonal.mem_antidiagonal.mp hij, hd]\n    have hia : Finsupp.weight w ij.1 = a := le_antisymm\n      (le_of_add_le_add_right ((add_le_add (le_refl (Finsupp.weight w ij.1)) hj').trans_eq hs)) hi'\n    have hjb : Finsupp.weight w ij.2 = b := by\n      rw [hia] at hs\n      exact add_left_cancel hs\n    simp [hia, hjb]\n  · rw [ite_eq_right hd]\n    symm\n    apply Finset.sum_eq_zero\n    intro ij hij\n    rw [MvPolynomial.coeff_weightedHomogeneousComponent,\n      MvPolynomial.coeff_weightedHomogeneousComponent]\n    by_cases hi : Finsupp.weight w ij.1 = a\n    · have hj : Finsupp.weight w ij.2 ≠ b := by\n        intro hj\n        apply hd\n        rw [← Finset.HasAntidiagonal.mem_antidiagonal.mp hij, map_add, hi, hj]\n      simp [hj]\n    · simp [hi]\n\nlemma component_ne_zero_of_attained (w : σ → ℝ≥0) (p : MvPolynomial σ k)\n    {d : σ →₀ ℕ} (hd : d ∈ p.support) :\n    MvPolynomial.weightedHomogeneousComponent w (Finsupp.weight w d) p ≠ 0 := by\n  classical\n  intro h\n  have hc := congrArg (fun p : MvPolynomial σ k => p.coeff d) h\n  simp only [MvPolynomial.coeff_weightedHomogeneousComponent, AddMonoidAlgebra.coeff_zero] at hc\n  exact MvPolynomial.mem_support_iff.mp hd hc\n\nsection Domain\nvariable [IsDomain k]\n\nlemma value_mul (w : σ → ℝ≥0) (p q : MvPolynomial σ k) :\n    value w (p*q) = value w p + value w q := by\n  classical\n  by_cases hp : p = 0\n  · simp [hp]\n  by_cases hq : q = 0\n  · simp [hq]\n  obtain ⟨a, ha, hea⟩ := value_attained w hp\n  obtain ⟨b, hb, heb⟩ := value_attained w hq\n  apply le_antisymm _ (le_value_mul w p q)\n  have hpa : ∀ d ∈ p.support, Finsupp.weight w a ≤ Finsupp.weight w d := by\n    intro d hd\n    exact ENNReal.coe_le_coe.mp (hea ▸ value_le_weight w hd)\n  have hqb : ∀ d ∈ q.support, Finsupp.weight w b ≤ Finsupp.weight w d := by\n    intro d hd\n    exact ENNReal.coe_le_coe.mp (heb ▸ value_le_weight w hd)\n  have hn : MvPolynomial.weightedHomogeneousComponent w\n      (Finsupp.weight w a + Finsupp.weight w b) (p*q) ≠ 0 := by\n    rw [component_mul_at_lower_bounds w p q _ _ hpa hqb]\n    exact mul_ne_zero (component_ne_zero_of_attained w p ha)\n      (component_ne_zero_of_attained w q hb)\n  obtain ⟨d, hd⟩ := MvPolynomial.support_nonempty.mpr hn\n  rw [MvPolynomial.support_weightedHomogeneousComponent, Finset.mem_filter] at hd\n  rw [hea, heb, ← ENNReal.coe_add, ← hd.2]\n  exact value_le_weight w hd.1\n\n/-- Weighted monomial valuation on the genuine polynomial coordinate ring. -/\ndef valuation (w : σ → ℝ≥0) : AddValuation (MvPolynomial σ k) ENNReal :=\n  AddValuation.of (value w) (value_zero w) (value_one w) (value_add w) (value_mul w)\n\n@[simp] lemma valuation_apply (w : σ → ℝ≥0) (p : MvPolynomial σ k) :\n    valuation w p = value w p := rfl\n\nend Domain\n\nsection Convex\nvariable {ι : Type*}\n\n/-- Coordinatewise nonnegative linear combination of weight vectors. -/\ndef combine (s : Finset ι) (c : ι → ℝ≥0) (w : ι → σ → ℝ≥0) : σ → ℝ≥0 :=\n  fun j => ∑ i ∈ s, c i * w i j\n\nlemma weight_combine (s : Finset ι) (c : ι → ℝ≥0) (w : ι → σ → ℝ≥0)\n    (d : σ →₀ ℕ) :\n    Finsupp.weight (combine s c w) d = ∑ i ∈ s, c i * Finsupp.weight (w i) d := by\n  classical\n  simp only [combine, Finsupp.weight_apply, Finsupp.sum,\n    nsmul_eq_mul, Finset.mul_sum]\n  rw [Finset.sum_comm]\n  apply Finset.sum_congr rfl\n  intro i hi\n  apply Finset.sum_congr rfl\n  intro j hj\n  ring\n\n/-- Nonnegative combinations dominate the corresponding combination of values.\nThe homogeneous inequality needs no normalization of the coefficients. -/\nlemma combine_dominates [IsDomain k] (s : Finset ι) (c : ι → ℝ≥0) (w : ι → σ → ℝ≥0)\n    (p : MvPolynomial σ k) :\n    ∑ i ∈ s, (c i : ENNReal) * valuation (w i) p ≤\n      valuation (combine s c w) p := by\n  change _ ≤ value _ p\n  apply (le_value_iff _).mpr\n  intro d hd\n  rw [weight_combine, ENNReal.ofNNReal_finsetSum]\n  simp_rw [ENNReal.coe_mul]\n  apply Finset.sum_le_sum\n  intro i hi\n  exact mul_le_mul_right (value_le_weight (w i) hd) _\n\n/-- Equality of two monomial weights is preserved by nonnegative combinations. -/\nlemma linear_equation_combine (s : Finset ι) (c : ι → ℝ≥0)\n    (w : ι → σ → ℝ≥0) (a b : σ →₀ ℕ)\n    (h : ∀ i ∈ s, Finsupp.weight (w i) a = Finsupp.weight (w i) b) :\n    Finsupp.weight (combine s c w) a = Finsupp.weight (combine s c w) b := by\n  rw [weight_combine, weight_combine]\n  apply Finset.sum_congr rfl\n  intro i hi\n  rw [h i hi]\n\nend Convex\nend CartierSections.Monomial\n\nend\n\nend OAI\n","OAI/AlgebraicGeometry/CartierSections/Weights.lean":"import Mathlib.Algebra.Order.Archimedean.Real.Basic\nimport Mathlib.Data.Finsupp.Interval\nimport Mathlib.LinearAlgebra.LinearIndependent.Defs\nimport Mathlib.Tactic\n\nnamespace OAI\n\n/-!\n# Real weights of exponent vectors\n\nReal weights are additive on exponent vectors. Positive weights have finite sublevel sets,\nand rationally independent weights distinguish exponents.\n-/\n\nopen scoped BigOperators\n\nnamespace CartierSections\n\nsection Weights\nvariable {ι : Type*} [Fintype ι]\n\nnoncomputable def realWeight (w : ι → ℝ) (d : ι →₀ ℕ) : ℝ :=\n  ∑ i, w i * (d i : ℝ)\n\n@[simp] theorem realWeight_zero (w : ι → ℝ) : realWeight w 0 = 0 := by\n  simp [realWeight]\n\n@[simp] theorem realWeight_add (w : ι → ℝ) (d e : ι →₀ ℕ) :\n    realWeight w (d + e) = realWeight w d + realWeight w e := by\n  simp [realWeight, Nat.cast_add, mul_add, Finset.sum_add_distrib]\n\n@[simp] theorem realWeight_nsmul (w : ι → ℝ) (n : ℕ) (d : ι →₀ ℕ) :\n    realWeight w (n • d) = n * realWeight w d := by\n  simp [realWeight, Finset.mul_sum, mul_left_comm]\n\ntheorem realWeight_nonneg {w : ι → ℝ} (hw : ∀ i, 0 ≤ w i) (d : ι →₀ ℕ) :\n    0 ≤ realWeight w d :=\n  Finset.sum_nonneg fun i _ => mul_nonneg (hw i) (Nat.cast_nonneg _)\n\ntheorem realWeight_injective {w : ι → ℝ} (hw : LinearIndependent ℚ w) :\n    Function.Injective (realWeight w) := by\n  intro d e h\n  have he : (fun i => (d i : ℚ)) = (fun i => (e i : ℚ)) :=\n    hw.fintypeLinearCombination_injective (by\n      simpa [Fintype.linearCombination_apply, realWeight, Algebra.smul_def, mul_comm] using h)\n  ext i\n  exact_mod_cast congrFun he i\n\n/-- Positive weights give finite sublevel sets of exponent vectors. -/\ntheorem finite_weight_sublevel {w : ι → ℝ} (hw : ∀ i, 0 < w i) (L : ℝ) :\n    {d : ι →₀ ℕ | realWeight w d ≤ L}.Finite := by\n  classical\n  let b : ι →₀ ℕ := Finsupp.equivFunOnFinite.symm (fun i => ⌈L / w i⌉₊)\n  apply (Set.finite_Iic b).subset\n  intro d hd\n  show d ≤ b\n  intro i\n  have hi : w i * (d i : ℝ) ≤ L :=\n    le_trans (Finset.single_le_sum\n      (fun j _ => mul_nonneg (hw j).le (Nat.cast_nonneg _)) (Finset.mem_univ i)) hd\n  change d i ≤ ⌈L / w i⌉₊\n  apply (Nat.cast_le (α := ℝ)).mp\n  exact (le_div_iff₀ (hw i)).mpr (by nlinarith) |>.trans (Nat.le_ceil _)\nend Weights\n\nend CartierSections\n\nend OAI\n","Submission.lean":"import OAI.AlgebraicGeometry.CartierSections.FieldTopology\nimport OAI.AlgebraicGeometry.CartierSections.FieldRetraction\n\nnamespace OAI\n\nnoncomputable section\nopen scoped BigOperators NNReal ENNReal\nnamespace CartierSections\nsection ClosedChartFieldTopology\nuniverse u\nlocal instance polynomialOrigin_isMaximal_topology {σ k : Type u} [Fintype σ] [Field k] :\n    (MvPolynomial.idealOfVars σ k).IsMaximal :=\n  polynomialOrigin_isMaximal\n\nvariable {σ k R A K : Type u} [Fintype σ] [Field k] [IsAlgClosed k]\n  [CommRing R] [CommRing A] [IsLocalRing R] [IsLocalRing A] [IsNoetherianRing A]\n  [IsDomain A] [Field K] [Algebra A K] [IsFractionRing A K]\n  [Algebra (MvPolynomial σ k) R] [Algebra (MvPolynomial σ k) A]\n  [Algebra k A] [IsScalarTower k (MvPolynomial σ k) A]\n  [Algebra R A] [IsScalarTower (MvPolynomial σ k) R A]\n  [IsLocalization.AtPrime R (MvPolynomial.idealOfVars σ k)]\n  [IsLocalHom (algebraMap R A)] [Algebra.FormallyUnramified R A]\n  [Algebra.EssFiniteType R A] [Algebra.FormallyEtale (MvPolynomial σ k) A]\n\nlemma isCompact_closedChartFieldRetraction_cone\n    (a : σ → NNReal) (ha : ∀ i, 0 < a i) :\n    IsCompact ((fun w : σ → NNReal => fun x : K =>\n      closedChartFieldRetraction (σ := σ) (k := k) (R := R) (A := A) w x) ''\n      normalizedWeights a) := by\n  simpa only [expandedFractionValuation, closedChartFieldRetraction,\n    closedChartRetraction] using\n    (isCompact_expandedFractionValuation_cone (K := K)\n      (closedChartExpansion (σ := σ) (k := k) (R := R) (A := A))\n      (closedChartExpansion_injective (σ := σ) (k := k) (R := R) (A := A)) a ha)\nend ClosedChartFieldTopology\nend CartierSections\n\nend\n\nend OAI\n"};
